"using System;
using System.IO;

namespace InventarioAutoProcessor
{
    public class FileLoggerService : ILoggerService
    {
        public void Log(string message)
        {
            WriteLog(message);
        }

        public void LogError(string message)
        {
            WriteLog($"ERROR: {message}");
        }

        private void WriteLog(string message)
        {
            try
            {
                string logDir = @"C:\Controlab-ia\Inventario\Logs";
                string logFile = Path.Combine(logDir, $"servicio_{DateTime.Now:yyyyMMdd}.log");

                Directory.CreateDirectory(logDir);

                string logMessage = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}";
                File.AppendAllText(logFile, logMessage + Environment.NewLine);
            }
            catch (Exception)
            {
                // Fallback
                try
                {
                    string fallbackLog = @"C:\Windows\Temp\controlab_service.log";
                    File.AppendAllText(fallbackLog, $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}" + Environment.NewLine);
                }
                catch { }
            }
        }
    }
}"

"using System;
using System.Collections.Generic;
using ClosedXML.Excel;
using System.IO;

namespace InventarioAutoProcessor
{
    public class ExcelParser : IFileParser
    {
        private readonly ILoggerService _logger;

        public ExcelParser(ILoggerService logger)
        {
            _logger = logger;
        }

        public bool SupportsExtension(string extension)
        {
            return extension == ".xlsx" || extension == ".xls";
        }

        public IEnumerable<(string nombrePrueba, int cantidad)> Parse(string filePath)
        {
            _logger.Log($"PROCESANDO EXCEL: {Path.GetFileName(filePath)}");
            var results = new List<(string, int)>();

            using (var workbook = new XLWorkbook(filePath))
            {
                var worksheet = workbook.Worksheet(1);
                var usedRange = worksheet.RangeUsed();

                if (usedRange == null)
                    throw new Exception("Archivo Excel vacío");

                foreach (var row in usedRange.RowsUsed())
                {
                    if (row.RowNumber() == 1) continue;

                    try
                    {
                        string nombrePrueba = row.Cell(1).GetString().Trim();
                        string cantidadStr = row.Cell(2).GetString().Trim();

                        if (string.IsNullOrEmpty(nombrePrueba))
                            continue;

                        if (int.TryParse(cantidadStr, out int cantidad) && cantidad > 0)
                        {
                            results.Add((nombrePrueba, cantidad));
                        }
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError($"Fila {row.RowNumber()}: {ex.Message}");
                    }
                }
            }
            return results;
        }
    }
}"

