                {
                    cmd.Parameters.AddWithValue("@prueba", nombrePrueba);
                    cmd.Parameters.AddWithValue("@cantidad", cantidad);
                    cmd.Parameters.AddWithValue("@archivo", "AutoProcessor");

                    conn.Open();
                    cmd.ExecuteNonQuery();
                }
            }
        }
    }
}"

