"const prisma = require('../../core/prisma');

class InventoryRepository {
  async findAllActive() {
    return prisma.itemInventario.findMany({
      where: { activo: 1 },
      orderBy: { fecha_creacion: 'desc' }
    });
  }

  async create(data) {
    // Extraer solo los campos que existen en Prisma para evitar errores
    const {
      codigo, nombre, descripcion, categoria, unidad, stock_actual,
      stock_minimo, stock_critico, proveedor, precio_costo, precio_venta,
      ubicacion, fecha_vencimiento
    } = data;

    return prisma.itemInventario.create({
      data: {
        codigo, nombre, descripcion, categoria, unidad, stock_actual,
        stock_minimo, stock_critico, proveedor, precio_costo, precio_venta,
        ubicacion, 
        fecha_vencimiento: fecha_vencimiento ? new Date(fecha_vencimiento) : null,
        creado_por: 1
      }
    });
  }

  async update(id, data) {
    const {
      codigo, nombre, descripcion, categoria, unidad,
      stock_minimo, stock_critico, proveedor, precio_costo, precio_venta,
      ubicacion, fecha_vencimiento
    } = data;

    return prisma.itemInventario.updateMany({
      where: { 
        id: parseInt(id),
        activo: 1 
      },
      data: {
        codigo, nombre, descripcion, categoria, unidad,
        stock_minimo, stock_critico, proveedor, precio_costo, precio_venta,
        ubicacion,
        fecha_vencimiento: fecha_vencimiento ? new Date(fecha_vencimiento) : null
      }
    });
  }
}

module.exports = new InventoryRepository();"

"const inventoryRepository = require('./inventory.repository');

class InventoryService {
  async getAllItems() {
    return inventoryRepository.findAllActive();
  }

  async createItem(data) {
    return inventoryRepository.create(data);
  }

  async updateItem(id, data) {
    return inventoryRepository.update(id, data);
  }
}

module.exports = new InventoryService();"

"const inventoryService = require('./inventory.service');

class InventoryController {
  async getInventory(req, res) {
    try {
      console.log('📦 Obteniendo inventario (Screaming Architecture)...');
      const items = await inventoryService.getAllItems();
      console.log('✅ Inventario obtenido:', items.length, 'items');
      res.json({ items });
    } catch (error) {
      console.error('❌ Error inventario:', error.message);
      res.status(500).json({ error: error.message, items: [] });
    }
  }

  async createItem(req, res) {
    try {
      console.log('➕ Creando nuevo item:', req.body.nombre);
      await inventoryService.createItem(req.body);
      console.log('✅ Item creado exitosamente');
      res.json({ message: 'Item creado exitosamente' });
    } catch (error) {
      console.error('❌ Error creando item:', error.message);
      res.status(500).json({ error: 'Error creando item: ' + error.message });
    }
  }

  async updateItem(req, res) {
    try {
      const { id } = req.params;
      console.log('✏️ Editando item ID:', id, 'Nombre:', req.body.nombre);
      await inventoryService.updateItem(id, req.body);
      console.log('✅ Item editado exitosamente');
      res.json({ message: 'Item actualizado exitosamente' });
    } catch (error) {
      console.error('❌ Error editando item:', error.message);
      res.status(500).json({ error: 'Error editando item: ' + error.message });
    }
  }
}

module.exports = new InventoryController();"

"const express = require('express');
const router = express.Router();
const inventoryController = require('./inventory.controller');

router.get('/', inventoryController.getInventory);
router.post('/', inventoryController.createItem);
router.put('/:id', inventoryController.updateItem);

module.exports = router;"

