"const fs = require('fs');
const path = require('path');

const routesDir = path.join(__dirname, '..', '..', '..', '..', '..', 'controlab-ia', 'backend', 'routes');
console.log('Scanning routes directory:', routesDir);

try {
  const files = fs.readdirSync(routesDir);
  files.forEach(file => {
    if (!file.endsWith('.js') && !file.endsWith('.jsx')) return;
    const content = fs.readFileSync(path.join(routesDir, file), 'utf8');
    const lines = content.split('\n');
    const routes = [];

    lines.forEach((line, index) => {
      if (line.includes('router.get(') || line.includes('router.post(') || line.includes('router.put(') || line.includes('router.delete(')) {
        routes.push({ lineNum: index + 1, content: line.trim() });
      }
    });

    if (routes.length > 0) {
      console.log(`\n📄 File: routes/${file}`);
      routes.forEach(r => console.log(`   Line ${r.lineNum}: ${r.content}`));
    }
  });
} catch (e) {
  console.error('Error:', e);
}
"

