"const { getPool, sql } = require('../../../../backend/config/database');

async function testConnection() {
  try {
    console.log('🔌 Conectando a la base de datos...');
    const pool = await getPool();
    console.log('✅ Conexión exitosa.');

    // 1. Probar consulta a items_inventario
    console.log('\n📊 Consultando items_inventario...');
    const itemsResult = await pool.request().query('SELECT TOP 5 * FROM items_inventario');
    console.log(`✅ items_inventario: ${itemsResult.recordset.length} filas encontradas.`);
    console.log(itemsResult.recordset);

    // 2. Probar consulta a LotesReactivos
    console.log('\n📦 Consultando LotesReactivos...');
    const lotesResult = await pool.request().query('SELECT TOP 5 * FROM LotesReactivos');
    console.log(`✅ LotesReactivos: ${lotesResult.recordset.length} filas encontradas.`);
    console.log(lotesResult.recordset);

    // 3. Probar consulta a mapeo_pruebas_reactivos
    console.log('\n🗺️ Consultando mapeo_pruebas_reactivos...');
    const mapeoResult = await pool.request().query('SELECT TOP 5 * FROM mapeo_pruebas_reactivos');
    console.log(`✅ mapeo_pruebas_reactivos: ${mapeoResult.recordset.length} filas encontradas.`);
    console.log(mapeoResult.recordset);

    // 4. Probar consulta a tmp_importacion_examenes
    console.log('\n📥 Consultando tmp_importacion_examenes...');
    const tempResult = await pool.request().query('SELECT TOP 5 * FROM tmp_importacion_examenes');
    console.log(`✅ tmp_importacion_examenes: ${tempResult.recordset.length} filas encontradas.`);
    console.log(tempResult.recordset);

    process.exit(0);
  } catch (error) {
    console.error('❌ ERROR durante las pruebas:', error);
    process.exit(1);
  }
}

testConnection();
"

