  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (token) {
    jwt.verify(token, process.env.JWT_SECRET || 'mi_secreto_temporal', (err, user) => {
      if (!err) {
        req.user = user;
      }
    });
  }

  next();
};"

