"const baseURL = 'http://localhost:5000/api';

async function checkData() {
  try {
    // Login
    const response = await fetch(`${baseURL}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ usuario: 'admin', contraseña: 'admin123' })
    });
    const loginData = await response.json();
    const token = loginData.token;
    const headers = { 
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}` 
    };

    // Category Distribution
    const catRes = await fetch(`${baseURL}/dashboard/category-distribution`, { headers });
    const catData = await catRes.json();
    console.log('--- Category Distribution ---');
    console.log(JSON.stringify(catData, null, 2));

    // Stock Chart
    const stockRes = await fetch(`${baseURL}/dashboard/stock-chart`, { headers });
    const stockData = await stockRes.json();
    console.log('\n--- Stock Chart Data ---');
    console.log(JSON.stringify(stockData, null, 2));

  } catch (error) {
    console.error('Error:', error);
  }
}

checkData();
"

