"  const handlePreguntar = async () => {
    if (!pregunta.trim()) return;

    setLoading(true);
    try {
      // ✅ USAR API_BASE_URL
      const response = await fetch(`${API_BASE_URL}/reports/analyze`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ pregunta: pregunta })
      });

      const data = await response.json();

      setRespuesta(data);
      setHistorial([data, ...historial.slice(0, 4)]); // Mantener último 5
      setPregunta('');

    } catch (error) {
      console.error('Error:', error);
      alert('Error al procesar la pregunta');
    } finally {
      setLoading(false);
    }
  };

  const exportarAExcel = async (tipo = 'precios') => {
    try {
      let url = '';
      let body = null;
      let method = 'GET';

      if (tipo === 'precios') {
        // ✅ USAR API_BASE_URL
        url = `${API_BASE_URL}/reports/exportar-excel/precios`;
      } else if (tipo === 'ia' && respuesta && respuesta.datos) {
        // ✅ USAR API_BASE_URL
        url = `${API_BASE_URL}/reports/exportar-excel/ia`;
        method = 'POST';
        body = JSON.stringify({
          datos: respuesta.datos,
          nombreReporte: respuesta.tipo
        });
      } else {
        alert('No hay datos para exportar');
        return;
      }

      const options = {
        method: method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
      };

      if (body) {
        options.body = body;
      }

      const response = await fetch(url, options);"

